//! THE ORACLE TEST: our TTIR against what the existing Python toolchain emits.
//!
//! Needs the `ruff` feature: every case starts from Python SOURCE.
#![cfg(feature = "ruff")]
//!
//! The goldens are regenerated by
//! `tools/gen_ttir_goldens.py`, which writes TWO checkpoints per configuration:
//!
//!   * `<name>.ttir_raw.mlir` -- `ASTSource.make_ir(...)`, i.e. `code_generator.py`'s
//!     output. THIS is bridge one's oracle, because it is exactly what this crate ports.
//!   * `<name>.ttir.mlir` -- after `backend.make_ttir(...)`, which is a PASS PIPELINE
//!     (inliner, canonicalizer, ttir-combine, reorder-broadcast, cse, symbol-dce). That is
//!     bridge two's input, not ours; diffing against it would demand we also reproduce MLIR
//!     canonicalization.
//!
//! Comparison is STRUCTURAL and field by field -- see `triton_frontend::diff` for exactly
//! what is and is not compared. `planted_difference_*` below are the CONTROLS: without a
//! test that a deliberately-broken module is caught AND NAMED, a passing diff proves
//! nothing.

mod common;

use triton_frontend::codegen;
use triton_frontend::diff;
use triton_frontend::target::Target;
use triton_frontend::ttir::{self, Attr, Type};

/// Compile a fixture at `target` and compare it against its golden, printing the full
/// field-by-field report on failure.
///
/// # WHICH TARGET, AND WHY IT IS NOT ALWAYS SPYRE.
///
/// The goldens were produced by the real Triton, which HAS the `f16 / f16 -> f32` promotion
/// this crate deliberately turns off for Spyre (see `triton_frontend::target`). Five of the
/// seven configurations never reach a bare `/` on f16 -- `swiglu_mlp.py` uses `tl.fdiv`
/// precisely to dodge the promotion -- so they match under EITHER target, and
/// `every_matching_fixture_is_target_independent` asserts exactly that.
///
/// `attention_flash.py`'s epilogue is the exception: `acc = acc / l_i[:, None]` is a bare f16
/// divide, so the oracle widens it. Diffed with `upstream_gpu` it matches exactly, which is
/// what proves the PORT faithful; `tests/divergence.rs` then asserts that under `spyre` the
/// difference is exactly that divide and nothing else, which is what proves the DIVERGENCE
/// real and localized. Using one target for both jobs would have lost one of the two facts.
fn check_case_on(case: &common::Case, target: Target) {
    let name = &case.name;
    let kernel = &case.spec.kernel;
    let spec = &case.spec;
    // The golden NAME and the source FILE differ for the multi-configuration fixtures:
    // `swiglu_mlp_granite` is `swiglu_mlp.py` at Granite width.
    let src = common::fixture_src(&case.fixture);
    let golden = match common::golden(name) {
        Some(g) => g,
        None => panic!(
            "no golden for `{name}`: expected tests/goldens/{name}.ttir_raw.mlir. \
             Regenerate with tools/gen_ttir_goldens.py."
        ),
    };
    let ours = match codegen::compile(&src, spec, target) {
        Ok(m) => m,
        Err(e) => panic!("`{name}` ({kernel}) did not compile: {e}"),
    };
    let report = diff::compare_to_golden_text(&golden, &ours);
    if !report.ok() {
        eprintln!("---- OUR TTIR for {name} ----\n{}", ttir::print::print_module(&ours));
        panic!(
            "`{name}` does not match its golden structurally:\n{}",
            report.render()
        );
    }
    assert!(
        report.matched_ops > 0,
        "`{name}`: the diff reported no findings but also matched ZERO ops -- that is a \
         diff comparing nothing, not a pass"
    );
    eprintln!("{name}: {} op(s) matched structurally", report.matched_ops);
}

fn check_case(case: &common::Case) {
    check_case_on(case, Target::spyre());
}

/// [`check_case_on`] for a golden that is KNOWN STALE: the diff must yield exactly
/// `pinned_findings` findings, so the staleness is asserted rather than hidden. 0 findings
/// or a larger count both fail, forcing the entry back to [`check_case_on`] or a
/// re-recorded pin with a reason.
fn check_case_stale_on(case: &common::Case, target: Target, pinned_findings: usize) {
    let name = &case.name;
    let src = common::fixture_src(&case.fixture);
    let golden = common::golden(name).unwrap_or_else(|| {
        panic!("no golden for `{name}`: expected tests/goldens/{name}.ttir_raw.mlir")
    });
    let ours = codegen::compile(&src, &case.spec, target)
        .unwrap_or_else(|e| panic!("`{name}` did not compile: {e}"));
    let report = diff::compare_to_golden_text(&golden, &ours);
    let got = report.findings.len();
    assert!(
        report.matched_ops > 0,
        "`{name}`: the diff matched ZERO ops -- that is a diff comparing nothing"
    );
    assert_eq!(
        got, pinned_findings,
        "`{name}`: the stale-golden pin moved ({pinned_findings} recorded, {got} now): \
         regenerate the golden and use check_case_on, or re-record the pin AND file why.\n{}",
        report.render()
    );
}

/// The configurations that never reach a bare f16 divide, and so are target-independent.
fn target_independent_cases() -> Vec<common::Case> {
    vec![
        common::vector_add(),
        common::mul(),
        common::swiglu("swiglu_mlp", 128, 256, 128),
        common::swiglu("swiglu_mlp_granite", 4096, 12800, 4096),
        common::swiglu("swiglu_mlp_tiledk", 128, 256, 64),
        common::embedding("embedding", 512, 128),
        common::embedding("embedding_granite", 49159, 4096),
        common::rmsnorm("rmsnorm", 128),
        common::rmsnorm("rmsnorm_granite", 4096),
        common::rope("rope", 4),
        common::rope("rope_granite_q", 32),
        common::rope("rope_granite_kv", 8),
        common::decoder_layer(),
        common::decoder_two_layers(),
    ]
}

