#[test]
fn attention_flash_causal_matches_golden() {
    check_case_on(
        &common::attention("attention_flash_causal", 3),
        Target::upstream_gpu(),
    );
}

/// The five fixtures that avoid a bare f16 divide must match under BOTH targets.
///
/// This is the control that keeps the divergence honest in the other direction: if
/// `div_promotes_narrow_floats` ever started affecting anything other than a narrow-float
/// divide, these would stop agreeing.
#[test]
fn every_matching_fixture_is_target_independent() {
    for case in target_independent_cases() {
        let src = common::fixture_src(&case.fixture);
        let golden = common::golden(&case.name).expect("golden");
        for target in [Target::spyre(), Target::upstream_gpu()] {
            let m = codegen::compile(&src, &case.spec, target)
                .unwrap_or_else(|e| panic!("`{}` did not compile: {e}", case.name));
            let r = diff::compare_to_golden_text(&golden, &m);
            assert!(
                r.ok(),
                "`{}` should match its golden under EVERY target, but with {target:?} it has \
                 {} finding(s):\n{}",
                case.name,
                r.findings.len(),
                r.render()
            );
        }
    }
}

// ===----------------------------------------------------------------------===//
//   THE CONTROLS: a planted difference of each kind must be caught, BY NAME.
// ===----------------------------------------------------------------------===//

/// Compile vector_add and also parse its golden, so a mutation can be planted in one side.
fn both_sides() -> (ttir::Module, ttir::Module) {
    let src = common::fixture_src("vector_add");
    let golden = common::golden("vector_add").expect("vector_add golden");
    let expected = ttir::parse::parse_module(&golden)
        .unwrap_or_else(|e| panic!("golden did not parse: {e}"));
    let ours = codegen::compile(&src, &common::vector_add().spec, Target::spyre())
        .expect("vector_add compiles");
    (expected, ours)
}

fn findings_mentioning(report: &diff::Report, needle: &str) -> Vec<String> {
    report
        .findings
        .iter()
        .filter(|f| f.contains(needle))
        .cloned()
        .collect()
}

/// The baseline the controls depend on: unmutated, the two sides agree. If this fails the
/// controls below prove nothing either.
#[test]
fn control_baseline_is_clean() {
    let (expected, ours) = both_sides();
    let r = diff::compare(&expected, &ours);
    assert!(
        r.ok(),
        "the control baseline is not clean, so no planted-difference control below is \
         meaningful:\n{}",
        r.render()
    );
    assert!(r.matched_ops > 0, "baseline matched zero ops");
}

fn first_func_ops(m: &mut ttir::Module) -> &mut Vec<ttir::Op> {
    &mut m.funcs[0].body.blocks[0].ops
}

#[test]
fn control_planted_op_name_is_caught() {
    let (expected, mut ours) = both_sides();
    // `arith.addf` -> `arith.mulf`: the vector_add/mul distinction, i.e. the difference
    // that matters most and would be silent if the diff ignored op names.
    let mut hit = false;
    for op in first_func_ops(&mut ours) {
        if op.name == "arith.addf" {
            op.name = "arith.mulf".to_string();
            hit = true;
        }
    }
    assert!(hit, "control could not find an arith.addf to mutate");
    let r = diff::compare(&expected, &ours);
    let found = findings_mentioning(&r, ".name:");
    assert!(
        !found.is_empty() && found[0].contains("arith.addf") && found[0].contains("arith.mulf"),
        "a planted op-name change was not caught by name. Findings: {:?}",
        r.findings
    );
}

#[test]
fn control_planted_result_type_is_caught() {
    let (expected, mut ours) = both_sides();
    // Retype one `tt.descriptor_load` result from tensor<64xf16> to tensor<64xf32>.
    let target = first_func_ops(&mut ours)
        .iter()
        .find(|o| o.name == "tt.descriptor_load")
        .and_then(|o| o.results.first().copied())
        .expect("control could not find a tt.descriptor_load result");
    ours.values[target.0 as usize].ty = Type::tensor(&[64], Type::f32());
    let r = diff::compare(&expected, &ours);
    let found = findings_mentioning(&r, ".result_types:");
    assert!(
        !found.is_empty() && found[0].contains("tensor<64xf32>"),
        "a planted result-TYPE change was not caught by name. Findings: {:?}",
        r.findings
    );
}

#[test]
fn control_planted_shape_is_caught() {
    let (expected, mut ours) = both_sides();
    // Same element type, different SHAPE -- the failure a type-only comparison would miss.
    let target = first_func_ops(&mut ours)
        .iter()
        .find(|o| o.name == "tt.descriptor_load")
        .and_then(|o| o.results.first().copied())
        .expect("control could not find a tt.descriptor_load result");
    ours.values[target.0 as usize].ty = Type::tensor(&[128], Type::f16());
    let r = diff::compare(&expected, &ours);
    let found = findings_mentioning(&r, ".result_types:");
    assert!(
        !found.is_empty() && found[0].contains("tensor<128xf16>"),
        "a planted SHAPE change was not caught by name. Findings: {:?}",
        r.findings
    );
}

#[test]
fn control_planted_attribute_is_caught() {
    let (expected, mut ours) = both_sides();
    // Change a constant's value: 64 -> 63. Structurally identical otherwise.
    let mut hit = false;
    for op in first_func_ops(&mut ours) {
        if op.name == "arith.constant" {
            if let Some(Attr::Int(v, t)) = op.attrs.get("value").cloned() {
                if v == 64 {
                    op.attrs.insert("value".to_string(), Attr::Int(63, t));
                    hit = true;
                    break;
                }
            }
        }
    }
    assert!(hit, "control could not find an `arith.constant 64` to mutate");
    let r = diff::compare(&expected, &ours);
    let found = findings_mentioning(&r, ".attr[value]:");
    assert!(
        !found.is_empty() && found[0].contains("63"),
        "a planted ATTRIBUTE change was not caught by name. Findings: {:?}",
        r.findings
    );
}

#[test]
fn control_planted_predicate_is_caught() {
    let (expected, mut ours) = both_sides();
    // `arith.cmpi sle` -> `sgt`: the overflow check's bound direction.
    let mut hit = false;
    for op in first_func_ops(&mut ours) {
        if op.name == "arith.cmpi" {
            if let Some(Attr::Pred("sle")) = op.attrs.get("predicate") {
                op.attrs
                    .insert("predicate".to_string(), Attr::Pred("sgt"));
                hit = true;
                break;
            }
        }
    }
    assert!(hit, "control could not find an `arith.cmpi sle` to mutate");
    let r = diff::compare(&expected, &ours);
    let found = findings_mentioning(&r, ".attr[predicate]:");
    assert!(
        !found.is_empty() && found[0].contains("sgt"),
        "a planted PREDICATE change was not caught by name. Findings: {:?}",
        r.findings
    );
}

#[test]
fn control_planted_operand_swap_is_caught() {
    let (expected, mut ours) = both_sides();
    // Swap the two operands of the real `arith.muli` (the i32 one, whose operands differ):
    // same ops, same types, same counts, DIFFERENT dataflow.
    let mut hit = false;
    for op in first_func_ops(&mut ours) {
        if op.name == "arith.muli" && op.operands.len() == 2 && op.operands[0] != op.operands[1] {
            op.operands.swap(0, 1);
            hit = true;
            break;
        }
    }
    assert!(hit, "control could not find an `arith.muli` to mutate");
    let r = diff::compare(&expected, &ours);
    let found = findings_mentioning(&r, ".operands:");
    assert!(
        !found.is_empty(),
        "a planted OPERAND swap was not caught -- the diff is not comparing dataflow. \
         Findings: {:?}",
        r.findings
    );
}

#[test]
fn control_planted_missing_op_is_caught() {
    let (expected, mut ours) = both_sides();
    let before = first_func_ops(&mut ours).len();
    first_func_ops(&mut ours).retain(|o| o.name != "arith.andi");
    let after = first_func_ops(&mut ours).len();
    assert!(after < before, "control removed nothing");
    let r = diff::compare(&expected, &ours);
    let found = findings_mentioning(&r, ".op_count:");
    assert!(
        !found.is_empty(),
        "a planted op COUNT change was not caught. Findings: {:?}",
        r.findings
    );
    assert_eq!(
        r.actual_hist.get("arith.andi").copied().unwrap_or(0),
        0,
        "the histogram should show the removed op as absent"
    );
    assert!(
        r.expected_hist.get("arith.andi").copied().unwrap_or(0) > 0,
        "the histogram should show the golden still has it"
    );
}

#[test]
fn control_planted_loc_name_is_caught() {
    let (expected, mut ours) = both_sides();
    // The `loc` NAME is the Python variable, so it is AST-derived content, not cosmetics.
    let target = first_func_ops(&mut ours)
        .iter()
        .find(|o| o.name == "tt.get_program_id")
        .and_then(|o| o.results.first().copied())
        .expect("control could not find tt.get_program_id");
    let l = ours.values[target.0 as usize].loc.clone();
    ours.values[target.0 as usize].loc = l.named("NOT_pid");
    let r = diff::compare(&expected, &ours);
    let found = findings_mentioning(&r, ".result_loc_names:");
    assert!(
        !found.is_empty() && found[0].contains("NOT_pid"),
        "a planted loc-NAME change was not caught by name. Findings: {:?}",
        r.findings
    );
}

#[test]
fn control_planted_function_name_is_caught() {
    let (expected, mut ours) = both_sides();
    ours.funcs[0].name = "not_the_kernel".to_string();
    let r = diff::compare(&expected, &ours);
    assert!(
        findings_mentioning(&r, "MISSING in ours")
            .iter()
            .any(|f| f.contains("vector_add_kernel"))
            && findings_mentioning(&r, "EXTRA in ours")
                .iter()
                .any(|f| f.contains("not_the_kernel")),
        "a planted FUNCTION-name change was not caught by name. Findings: {:?}",
        r.findings
    );
}

/// The control that guards the control: a golden that does not parse must FAIL, never pass
/// silently. This is the specific way an oracle test can look green while comparing
/// nothing.
#[test]
fn control_unparsable_golden_fails_rather_than_passes() {
    let (_, ours) = both_sides();
    let r = diff::compare_to_golden_text("this is not MLIR at all", &ours);
    assert!(!r.ok(), "an unparsable golden must not compare clean");
    assert!(
        r.findings[0].contains("golden did not parse"),
        "the finding should say the golden did not parse, got {:?}",
        r.findings
    );
}
